#include <LVUI/Compiler.h>
#include <iostream>
#include <stdexcept>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
std::string compile(std::string_view source){auto result=lvui::compile_native(source);if(!result)throw std::runtime_error(result.error().message);return *result;}
void shape(){auto result=compile("import vm Model\nWindow { Image(source: vm.image(), width: 64, height: 48, fit: .Contain) }");check(result.find("#include <iiGUI/NativeImageView.h>")!=result.npos&&result.find("ii::gui::NativeImage::create(")!=result.npos&&result.find("ii::gui::ImageFit::contain")!=result.npos&&result.find("widgets.image(")==result.npos&&result.find("lvrs::")==result.npos,"iiGUI must own image geometry and painting");
    auto icon=compile("Window { Image(iconName: \"brush\") }");
    check(icon.find("#include <iiGUI/NativeIconView.h>")!=icon.npos&&icon.find("ii::gui::IconView::create(")!=icon.npos&&icon.find("<LVUI/NativeIcon.h>")==icon.npos&&icon.find("lvrs::")==icon.npos,"Named image did not use the iiGUI icon component");}
void bindings(){auto result=compile("import vm Model\nWindow { Image(source: vm.image(), width: vm.width(), height: vm.height(), backgroundColor: vm.background()) }");check(result.find("ii::gui::ImageInput")!=result.npos&&result.find(".width = lvui::native::number(")!=result.npos&&result.find("component.set_options(value)")!=result.npos&&result.find("set_image_options")==result.npos&&result.find("lvrs::")==result.npos,"Independent image fields did not bind without widget reconstruction");
    auto url=compile("import vm Model\nWindow { Image(source: \"file.svg\", imageLoader: vm.loader, width: 64, height: 32) }");
    check(url.find("#include <LVUI/NativeImageResolver.h>")!=url.npos&&url.find("lvui::native::Methods::evaluate(context")!=url.npos&&url.find("lvui::native::resolve_image<ii::gui::RasterImage>(")!=url.npos&&url.find("value.configuration.width, value.configuration.height")!=url.npos,"Image URL was not connected to an observable resolver");
    auto ambient=compile("Window { VStack {\n Image(source: \"one.svg\")\n Avatar(source: \"two.svg\")\n Card(type: .FilePreview, previewSource: \"three.svg\")\n ListItem(type: .Media, previewSource: \"four.svg\")\n } }");
    auto at=ambient.find("resolve_scoped_image<ii::gui::RasterImage>(");unsigned calls=0;while(at!=ambient.npos){++calls;at=ambient.find("resolve_scoped_image<ii::gui::RasterImage>(",at+1);}
    check(calls==4&&ambient.find("image_services")!=ambient.npos&&ambient.find("native_bindings->derive")!=ambient.npos,"Images do not share an activation-scoped resolver");}
void empty(){auto result=compile("Window { Image(fit: .Cover, circular: true, allowEmpty: true) }");check(result.find(".image = {}")!=result.npos&&result.find("ii::gui::ImageFit::cover")!=result.npos,"Empty asynchronous image placeholder was rejected");}
void diagnostics(){for(auto source:{"Window { Image(source: 123) }","Window { Avatar(source: 123) }","Window { Card(type: .File, previewSource: 123) }","Window { ListItem(type: .Media, previewSource: 123) }","Window { Image(fit: .Unknown) }","Window { Image(unknown: true) }","import vm Model\nWindow { Image(imageLoader: vm.loader) }","Window { Image(source: \"file.svg\", imageLoader: \"bad\") }","Window { Image(iconName: \"brush\", source: \"other.svg\") }","Window { Image(iconName: \"brush\", width: 20) }","Window { Image(iconSize: 18) }","Window { Image(iconName: \"\") }","Window { Image(iconName: \"brush\", iconSize: 0) }"}){auto result=lvui::compile_native(source);check(!result&&result.error().line>0&&result.error().column>0,"Invalid Image input lost source diagnostics");}auto result=lvui::compile_native("Window { Image() }");check(bool(result)&&result->find("lvrs::")==result->npos,"Default image path depends on LVRS");}
}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"shape";if(name=="shape")shape();else if(name=="bindings")bindings();else if(name=="empty")empty();else if(name=="diagnostics")diagnostics();else throw std::runtime_error("Unknown native Image compiler case");std::cout<<"Image compiler "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
